The DTO and the handler that shipped:

// enrollments/dto/enroll.dto.ts
export class EnrollDto {
  courseId: string;
  email: string;
  plan: "free" | "premium";
}

// enrollments/enrollments.controller.ts
@Post()
enroll(@Body() dto: EnrollDto) {
  return this.enrollments.enroll(dto);
}

// main.ts
app.useGlobalPipes(new ValidationPipe({ transform: true }));

curl -i -X POST https://api.codedev.test/enrollments -H "Content-Type: application/json" \
  -d '{"courseId":"c_1042","email":"ana@codedev.test","plan":"PREMIUM"}'
HTTP/1.1 201 Created

Statement: "Turning on \"strict\": true in tsconfig.json would make this request fail, because \"PREMIUM\" is not assignable to the type \"free\" | \"premium\"."

A receipt option was added to the DTO:

export class EnrollDto {
  // courseId, email, plan as before, with their decorators
  @IsBoolean()
  sendReceipt: boolean;
}

// main.ts
app.useGlobalPipes(new ValidationPipe({
  transform: true,
  transformOptions: { enableImplicitConversion: true },
}));

Request body: {"courseId":"c_1042","email":"ana@codedev.test","plan":"premium","sendReceipt":"false"}
Response: 201 Created

SELECT send_receipt FROM enrollments ORDER BY created_at DESC LIMIT 1;
